          enrichOneFitnessEqu: function (weymon) {
            let mythias = yuriana("scr_data");
            let alexsa = yuriana("scr_data2");
            var tysheena = 0;
            let amie = yuriana("scr_public");
            tysheena = 12;
            amie.initUserData(mythias);
            let araelynn = amie.getFitnessEquModelByCode(weymon.code);
            if (araelynn.type == "fitEqu2") {
              var yemaryam = 5;
              let golden = Math.random() * 100;
              yemaryam = "gemkcm";
              let terrill = 25;
              let miyuki = 0;
              if (amie.hasAchieve("cj_real_1_zige") && amie.hasSupportOver(8)) {
                miyuki = 5;
              }
              if (golden <= terrill + miyuki) {
                weymon.statusObj = new StatusVO("开放中");
              } else if (golden <= 40 + miyuki) {
                if (amie.hasSupportOver(39)) {
                  weymon.statusObj = new StatusVO("保养中");
                } else {
                  weymon.statusObj = new StatusVO("保养中", "保养中", amie.getColorGray());
                }
              } else if (golden <= 70 + miyuki) {
                weymon.statusObj = new StatusVO("贵宾专用", "贵宾专用", amie.getColorYellow());
              } else if (golden <= 100) {
                weymon.statusObj = new StatusVO("维护中", "维护中", amie.getColorGray());
              } else {
                weymon.statusObj = new StatusVO("特殊事件", "特殊事件", amie.getColorGreen());
              }
              let akashdeep = mythias.lastFitness2EquStatus[weymon.code];
              if ("undefined" == typeof akashdeep) {
                akashdeep = {};
              }
              if (akashdeep.code == weymon.statusObj.code) {
                akashdeep.times = amie.getNum(akashdeep.times) + 1;
              } else {
                akashdeep = {
                  code: weymon.statusObj.code,
                  times: 1
                };
              }
              if (akashdeep.code == "维护中" && akashdeep.times >= 3) {
                weymon.statusObj = new StatusVO("开放中");
                akashdeep = {
                  code: weymon.statusObj.code,
                  times: 1
                };
              }
              mythias.lastFitness2EquStatus[weymon.code] = akashdeep;
            }
          },
